108	    public ResponseEntity<ProblemDetail> handleOther(Exception ex, HttpServletRequest req) {
109	        if (ex instanceof ErrorResponse er) {
110	            ProblemDetail pd = er.getBody();
111	            pd.setInstance(URI.create(req.getRequestURI()));
112	            return ResponseEntity.status(er.getStatusCode()).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
113	        }
114	        log.error("unhandled exception", ex);
115	        return internal(ex, req);
116	    }
117	
118	    private ResponseEntity<ProblemDetail> internal(Exception ex, HttpServletRequest req) {
119	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.INTERNAL_SERVER_ERROR, "internal server error");
120	        pd.setTitle("Internal server error");
121	        pd.setType(URI.create("https://example.com/problems/internal-error"));
122	        pd.setInstance(URI.create(req.getRequestURI()));
123	        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
124	                .contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
125	    }
126	
127	    private ResponseEntity<ProblemDetail> build(ErrorCode code, String detail, HttpServletRequest req,
128	                                                List<Map<String, String>> errors) {
129	        HttpStatusCode status = code.status();
130	        ProblemDetail pd = ProblemDetail.forStatusAndDetail(status, detail);
131	        pd.setType(URI.create(code.typeUri()));
132	        pd.setTitle(code.title());
133	        pd.setInstance(URI.create(req.getRequestURI()));
134	        pd.setProperty("code", code.name());
135	        if (errors != null && !errors.isEmpty()) {
136	            pd.setProperty("errors", errors);
137	        }
138	        return ResponseEntity.status(status).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(pd);
139	    }
140	
141	    private static Map<String, String> fieldError(MessageSourceResolvable e) {
142	        String field = e instanceof FieldError fe ? fe.getField() : "";
143	        String msg = e.getDefaultMessage() == null ? "invalid" : e.getDefaultMessage();
144	        return Map.of("field", field, "message", msg);
145	    }
146	
147	    private static String constraintName(Throwable t) {
148	        for (Throwable c = t; c != null; c = c.getCause()) {
149	            if (c instanceof org.hibernate.exception.ConstraintViolationException cve
150	                    && cve.getConstraintName() != null) {
151	                return cve.getConstraintName().toLowerCase();
152	            }
153	        }
154	        for (Throwable c = t; c != null; c = c.getCause()) {
155	            String m = c.getMessage();
156	            if (m != null) {
157	                String lower = m.toLowerCase();
158	                if (lower.contains("uk_coupons_code")) return "uk_coupons_code";
159	                if (lower.contains("uk_orders_coupon_user_active")) return "uk_orders_coupon_user_active";
160	            }
161	        }
162	        return null;
163	    }
164	}
