3	import com.fasterxml.jackson.core.JsonProcessingException;
4	import com.fasterxml.jackson.databind.MapperFeature;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import com.fasterxml.jackson.databind.SerializationFeature;
7	import com.fasterxml.jackson.databind.json.JsonMapper;
8	import java.nio.charset.StandardCharsets;
9	import java.security.MessageDigest;
10	import java.security.NoSuchAlgorithmException;
11	import java.util.HexFormat;
12	import java.util.function.Supplier;
13	import org.springframework.http.HttpHeaders;
14	import org.springframework.http.HttpStatusCode;
15	import org.springframework.http.MediaType;
16	import org.springframework.http.ResponseEntity;
17	import org.springframework.stereotype.Component;
18	
19	/** begin -> 업무 처리(자체 트랜잭션) -> complete/release. 이 클래스와 호출 컨트롤러는 트랜잭션을 열지 않는다. */
20	@Component
21	public class IdempotentExecutor {
22	    private static final ObjectMapper CANONICAL_MAPPER = JsonMapper.builder()
23	            .enable(MapperFeature.SORT_PROPERTIES_ALPHABETICALLY)
24	            .enable(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS)
25	            .build();
26	
27	    private final IdempotencyService service;
28	    private final ObjectMapper objectMapper;
29	
30	    public IdempotentExecutor(IdempotencyService service, ObjectMapper objectMapper) {
31	        this.service = service;
32	        this.objectMapper = objectMapper;
33	    }
34	
35	    /** 요청 지문 (설계 01 4.2). xUserId == null 이면 "-". */
36	    public String fingerprint(IdempotencyScope scope, String xUserId, String path, Object requestDto) {
37	        try {
38	            String canonicalBody = CANONICAL_MAPPER.writeValueAsString(requestDto);
39	            String userPart = xUserId == null ? "-" : "U:" + xUserId;
40	            String src = scope.name() + "\n" + userPart + "\n" + path + "\n" + canonicalBody;
41	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(src.getBytes(StandardCharsets.UTF_8));
42	            return HexFormat.of().formatHex(digest);
43	        } catch (JsonProcessingException | NoSuchAlgorithmException e) {
44	            throw new IllegalStateException(e);
45	        }
46	    }
47	
48	    public ResponseEntity<Object> execute(IdempotencyScope scope, String key, String fingerprint,
49	                                          Supplier<IdemResult> action) {
50	        BeginResult begun = service.begin(scope, key, fingerprint);
51	        if (begun instanceof BeginResult.Replay replay) {
52	            try {
53	                return response(replay.status(), objectMapper.readTree(replay.body()), replay.location());
54	            } catch (JsonProcessingException e) {
55	                throw new IllegalStateException(e);
56	            }
57	        }
58	        long id = ((BeginResult.Owner) begun).id();
59	        IdemResult result;
60	        try {
61	            result = action.get();
62	        } catch (RuntimeException | Error t) {
63	            service.release(id);
64	            throw t;
65	        }
66	        if (result.status() >= 200 && result.status() < 300) {
67	            try {
68	                service.complete(id, result.status(), objectMapper.writeValueAsString(result.body()), result.location());
69	            } catch (JsonProcessingException e) {
70	                throw new IllegalStateException(e);
71	            }
72	        } else {
73	            service.release(id);
74	        }
75	        return response(result.status(), result.body(), result.location());
76	    }
77	
78	    private static ResponseEntity<Object> response(int status, Object body, String location) {
79	        ResponseEntity.BodyBuilder b = ResponseEntity.status(HttpStatusCode.valueOf(status))
80	                .contentType(MediaType.APPLICATION_JSON);
81	        if (location != null) {
82	            b.header(HttpHeaders.LOCATION, location);
83	        }
84	        return b.body(body);
85	    }
86	}
