1	package com.example.order.idempotency;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ErrorCode;
5	import com.example.order.common.Times;
6	import java.time.Clock;
7	import java.util.List;
8	import org.springframework.jdbc.core.JdbcTemplate;
9	import org.springframework.jdbc.core.ResultSetExtractor;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Propagation;
12	import org.springframework.transaction.annotation.Transactional;
13	
14	/**
15	 * 멱등 키 저장소. 호출자는 업무 트랜잭션 바깥에서 begin/complete/release 를 순차 호출해야 한다
16	 * (각 메서드는 자체 짧은 트랜잭션).
17	 */
18	@Service
19	public class IdempotencyService {
20	    private static final String INSERT_SQL = """
21	            INSERT INTO idempotency_keys (scope, idem_key, request_hash, status, created_at)
22	            VALUES (?, ?, ?, 'IN_PROGRESS', ?)
23	            ON CONFLICT (scope, idem_key) DO NOTHING
24	            RETURNING id""";
25	    private static final String SELECT_SQL = """
26	            SELECT id, request_hash, status, response_status, response_body, response_location
27	            FROM idempotency_keys WHERE scope = ? AND idem_key = ?""";
28	
29	    private record Row(long id, String hash, String status, Integer responseStatus, String body, String location) {
30	    }
31	
32	    private final JdbcTemplate jdbc;
33	    private final Clock clock;
34	
35	    public IdempotencyService(JdbcTemplate jdbc, Clock clock) {
36	        this.jdbc = jdbc;
37	        this.clock = clock;
38	    }
39	
40	    @Transactional(propagation = Propagation.REQUIRES_NEW)
41	    public BeginResult begin(IdempotencyScope scope, String key, String fingerprint) {
42	        for (int attempt = 0; attempt < 3; attempt++) {
43	            Long id = jdbc.query(INSERT_SQL, (ResultSetExtractor<Long>) rs -> rs.next() ? rs.getLong(1) : null,
44	                    scope.name(), key, fingerprint, Times.now(clock));
45	            if (id != null) {
46	                return new BeginResult.Owner(id);
47	            }
48	            List<Row> rows = jdbc.query(SELECT_SQL, (rs, i) -> new Row(rs.getLong("id"), rs.getString("request_hash"),
49	                    rs.getString("status"), (Integer) rs.getObject("response_status"), rs.getString("response_body"),
50	                    rs.getString("response_location")), scope.name(), key);
51	            if (rows.isEmpty()) {
52	                continue; // 선점자가 그 사이 release 함
53	            }
54	            Row r = rows.get(0);
55	            if (!r.hash().equals(fingerprint)) {
56	                throw new ApiException(ErrorCode.IDEMPOTENCY_KEY_MISMATCH,
57	                        "Idempotency-Key was already used with a different request");
58	            }
59	            if ("COMPLETED".equals(r.status())) {
60	                return new BeginResult.Replay(r.responseStatus(), r.body(), r.location());
61	            }
62	            throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS,
63	                    "a request with this Idempotency-Key is in progress");
64	        }
65	        throw new ApiException(ErrorCode.IDEMPOTENCY_IN_PROGRESS, "a request with this Idempotency-Key is in progress");
66	    }
67	
68	    @Transactional(propagation = Propagation.REQUIRES_NEW)
69	    public void complete(long id, int status, String body, String location) {
70	        jdbc.update("""
71	                UPDATE idempotency_keys
72	                SET status = 'COMPLETED', response_status = ?, response_body = ?, response_location = ?, completed_at = ?
73	                WHERE id = ? AND status = 'IN_PROGRESS'""", status, body, location, Times.now(clock), id);
74	    }
75	
76	    @Transactional(propagation = Propagation.REQUIRES_NEW)
77	    public void release(long id) {
78	        jdbc.update("DELETE FROM idempotency_keys WHERE id = ? AND status = 'IN_PROGRESS'", id);
79	    }
80	}
