12	
13	/** 커서: base64url("v1:{createdAtEpochMicros}:{id}") */
14	public record OrderCursor(long epochMicros, long id) {
15	    private static final Pattern FORMAT = Pattern.compile("^v1:(-?\\d{1,19}):(\\d{1,19})$");
16	    // PostgreSQL timestamptz 범위 안전 구간 (0001-01-01 ~ 9999-12-31)
17	    private static final long MIN_MICROS = -62_135_596_800L * 1_000_000L;
18	    private static final long MAX_MICROS = 253_402_300_799L * 1_000_000L;
19	
20	    public static OrderCursor of(OrderEntity o) {
21	        Instant i = o.getCreatedAt().toInstant();
22	        return new OrderCursor(i.getEpochSecond() * 1_000_000L + i.getNano() / 1_000, o.getId());
23	    }
24	
25	    public String encode() {
26	        String raw = "v1:" + epochMicros + ":" + id;
27	        return Base64.getUrlEncoder().withoutPadding().encodeToString(raw.getBytes(StandardCharsets.UTF_8));
28	    }
29	
30	    public static OrderCursor decode(String cursor) {
31	        try {
32	            String raw = new String(Base64.getUrlDecoder().decode(cursor), StandardCharsets.UTF_8);
33	            Matcher m = FORMAT.matcher(raw);
34	            if (!m.matches()) {
35	                throw bad();
36	            }
37	            long micros = Long.parseLong(m.group(1));
38	            long id = Long.parseLong(m.group(2));
39	            if (id <= 0 || micros < MIN_MICROS || micros > MAX_MICROS) {
40	                throw bad();
41	            }
42	            return new OrderCursor(micros, id);
43	        } catch (IllegalArgumentException e) { // Base64 / NumberFormatException
44	            throw bad();
45	        }
46	    }
47	
48	    public OffsetDateTime createdAt() {
49	        Instant i = Instant.ofEpochSecond(Math.floorDiv(epochMicros, 1_000_000L),
50	                Math.floorMod(epochMicros, 1_000_000L) * 1_000L);
51	        return i.atOffset(ZoneOffset.UTC);
52	    }
53	
54	    private static ApiException bad() {
55	        return new ApiException(ErrorCode.VALIDATION_ERROR, "cursor is invalid");
56	    }
57	}
