1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ErrorCode;
5	import com.example.order.common.Times;
6	import com.example.order.coupon.Coupon;
7	import com.example.order.coupon.CouponRepository;
8	import com.example.order.payment.PaymentGatewayClient;
9	import com.example.order.product.Product;
10	import java.time.Clock;
11	import java.time.OffsetDateTime;
12	import java.time.temporal.ChronoUnit;
13	import java.util.ArrayList;
14	import java.util.List;
15	import java.util.Map;
16	import java.util.stream.Collectors;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.annotation.Transactional;
19	
20	/** 주문 생성 / 취소·환불 / 배송 / 만료. 각 public 메서드가 하나의 업무 트랜잭션이다. */
21	@Service
22	public class OrderService {
23	    private final OrderRepository orderRepository;
24	    private final CouponRepository couponRepository;
25	    private final OrderInventory inventory;
26	    private final PaymentGatewayClient pgClient;
27	    private final OrderProperties properties;
28	    private final Clock clock;
29	
30	    public OrderService(OrderRepository orderRepository, CouponRepository couponRepository, OrderInventory inventory,
31	                        PaymentGatewayClient pgClient, OrderProperties properties, Clock clock) {
32	        this.orderRepository = orderRepository;
33	        this.couponRepository = couponRepository;
34	        this.inventory = inventory;
35	        this.pgClient = pgClient;
36	        this.properties = properties;
37	        this.clock = clock;
38	    }
39	
40	    @Transactional
41	    public OrderResponse create(String userId, CreateOrderRequest req) {
42	        OffsetDateTime now = Times.now(clock);
43	
44	        // 상품 락: productId 오름차순 (inventory.lockProducts 는 order by id)
45	        List<Long> ids = req.items().stream().map(CreateOrderRequest.Item::productId).toList();
46	        Map<Long, Product> products = inventory.lockProducts(ids);
47	        if (products.size() < ids.size()) {
48	            List<Long> missing = ids.stream().filter(i -> !products.containsKey(i)).sorted().toList();
49	            throw new ApiException(ErrorCode.PRODUCT_NOT_FOUND, "product(s) not found: " + missing);
50	        }
51	
52	        Coupon coupon = null;
53	        if (req.couponCode() != null) {
54	            coupon = couponRepository.lockByCode(req.couponCode()).orElseThrow(
55	                    () -> new ApiException(ErrorCode.COUPON_NOT_FOUND, "coupon " + req.couponCode() + " not found"));
56	        }
57	
58	        // 재고 검사
59	        for (CreateOrderRequest.Item item : req.items()) {
60	            Product p = products.get(item.productId());
61	            if (p.available() < item.quantity()) {
62	                throw new ApiException(ErrorCode.INSUFFICIENT_STOCK, "product " + p.getId() + ": available "
63	                        + p.available() + ", requested " + item.quantity());
64	            }
65	        }
66	
67	        long subtotal = 0;
68	        for (CreateOrderRequest.Item item : req.items()) {
69	            subtotal = Math.addExact(subtotal, Math.multiplyExact(products.get(item.productId()).getPrice(),
70	                    (long) item.quantity()));
71	        }
72	
73	        long discount = 0;
74	        if (coupon != null) {
75	            if (now.isBefore(coupon.getValidFrom()) || !now.isBefore(coupon.getValidUntil())) {
76	                throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "coupon is outside its validity period");
77	            }
78	            if (subtotal < coupon.getMinOrderAmount()) {
79	                throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE,
80	                        "subtotal is below the coupon's minimum order amount");
81	            }
82	            if (orderRepository.existsInUse(coupon.getCode(), userId, OrderStatus.COUPON_IN_USE)) {
83	                throw new ApiException(ErrorCode.COUPON_NOT_APPLICABLE, "coupon is already in use by this user");
84	            }
85	            if (coupon.getUsedCount() >= coupon.getTotalQuantity()) {
86	                throw new ApiException(ErrorCode.COUPON_EXHAUSTED, "coupon has no remaining quantity");
87	            }
88	            discount = coupon.discountFor(subtotal);
89	        }
90	
91	        OffsetDateTime expiresAt = now.plus(properties.paymentTtl()).truncatedTo(ChronoUnit.MICROS);
92	        OrderEntity order = new OrderEntity(userId, coupon == null ? null : coupon.getCode(), subtotal, discount,
93	                subtotal - discount, now, Times.normalize(expiresAt));
94	        for (CreateOrderRequest.Item item : req.items()) {
95	            Product p = products.get(item.productId());
96	            p.reserve(item.quantity());
97	            order.addItem(p.getId(), item.quantity(), p.getPrice());
98	        }
99	        if (coupon != null) {
100	            coupon.use();
101	        }
102	        orderRepository.saveAndFlush(order);
103	        return OrderResponse.from(order);
104	    }
105	
106	    @Transactional
107	    public OrderResponse cancel(long id) {
108	        OrderEntity order = lockOrder(id);
109	        OffsetDateTime now = Times.now(clock);
110	        switch (order.getStatus()) {
111	            case PENDING_PAYMENT -> {
112	                if (!now.isBefore(order.getExpiresAt())) {
113	                    throw new ApiException(ErrorCode.INVALID_STATE, "order payment window has expired");
114	                }
115	                inventory.releaseReservation(order);
116	                inventory.restoreCoupon(order);
117	                order.transitionTo(OrderStatus.CANCELLED);
118	            }
119	            case PAID -> {
120	                if (order.getPaymentId() != null) {
121	                    pgClient.refund(order.getPaymentId()); // 장애 시 예외 -> 롤백 -> 503
122	                }
123	                inventory.restoreStock(order);
124	                inventory.restoreCoupon(order);
125	                order.transitionTo(OrderStatus.REFUNDED);
126	            }
127	            default -> throw invalidState(order);
128	        }
129	        orderRepository.flush();
130	        return OrderResponse.from(order);
131	    }
132	
133	    @Transactional
134	    public OrderResponse ship(long id) {
135	        return advance(id, OrderStatus.PAID, OrderStatus.SHIPPED);
136	    }
137	
138	    @Transactional
139	    public OrderResponse deliver(long id) {
140	        return advance(id, OrderStatus.SHIPPED, OrderStatus.DELIVERED);
141	    }
142	
143	    private OrderResponse advance(long id, OrderStatus from, OrderStatus to) {
144	        OrderEntity order = lockOrder(id);
145	        if (order.getStatus() != from) {
146	            throw invalidState(order);
147	        }
148	        order.transitionTo(to);
149	        return OrderResponse.from(order);
150	    }
151	
152	    /** 만료 스윕: 주문 하나당 트랜잭션 하나. 이미 처리됐거나 락 중이면 false. */
153	    @Transactional
154	    public boolean expireIfDue(long id) {
155	        OffsetDateTime now = Times.now(clock);
156	        var locked = orderRepository.lockDueSkipLocked(id, now);
157	        if (locked.isEmpty()) {
158	            return false;
159	        }
160	        OrderEntity order = locked.get();
161	        inventory.releaseReservation(order);
162	        inventory.restoreCoupon(order);
163	        order.transitionTo(OrderStatus.EXPIRED);
164	        orderRepository.flush();
165	        return true;
166	    }
167	
168	    private OrderEntity lockOrder(long id) {
169	        return orderRepository.lockById(id)
170	                .orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND, "order " + id + " not found"));
171	    }
172	
173	    private static ApiException invalidState(OrderEntity order) {
174	        return new ApiException(ErrorCode.INVALID_STATE, "order " + order.getId() + " is " + order.getStatus());
175	    }
176	}
