1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ErrorCode;
5	import com.example.order.common.Times;
6	import com.example.order.payment.PaymentGatewayClient;
7	import com.example.order.payment.PgPaymentResult;
8	import java.time.Clock;
9	import java.time.OffsetDateTime;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	
13	/** 결제의 업무 트랜잭션. 주문 행 락을 쥔 채 PG 를 호출한다 (동시 결제 직렬화, R10.5). */
14	@Service
15	public class PaymentTxService {
16	
17	    public record PayOutcome(boolean declined, OrderResponse order) {
18	    }
19	
20	    private final OrderRepository orderRepository;
21	    private final OrderInventory inventory;
22	    private final PaymentGatewayClient pgClient;
23	    private final Clock clock;
24	
25	    public PaymentTxService(OrderRepository orderRepository, OrderInventory inventory, PaymentGatewayClient pgClient,
26	                            Clock clock) {
27	        this.orderRepository = orderRepository;
28	        this.inventory = inventory;
29	        this.pgClient = pgClient;
30	        this.clock = clock;
31	    }
32	
33	    @Transactional
34	    public PayOutcome payInTx(long id, String idempotencyKey, String cardToken) {
35	        OrderEntity order = orderRepository.lockById(id)
36	                .orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND, "order " + id + " not found"));
37	        OffsetDateTime now = Times.now(clock);
38	        if (order.getStatus() != OrderStatus.PENDING_PAYMENT || !now.isBefore(order.getExpiresAt())) {
39	            throw new ApiException(ErrorCode.INVALID_STATE,
40	                    "order " + id + " cannot be paid (status " + order.getStatus() + ")");
41	        }
42	
43	        boolean approved = true;
44	        String paymentId = null;
45	        if (order.getTotalPrice() > 0) {
46	            PgPaymentResult result = pgClient.pay(idempotencyKey, id, order.getTotalPrice(), cardToken);
47	            approved = result.approved();
48	            paymentId = result.paymentId();
49	        }
50	
51	        if (approved) {
52	            inventory.sell(order);
53	            order.markPaid(paymentId, Times.now(clock));
54	        } else {
55	            inventory.releaseReservation(order);
56	            inventory.restoreCoupon(order);
57	            order.markPaymentFailed(paymentId);
58	        }
59	        orderRepository.flush();
60	        return new PayOutcome(!approved, OrderResponse.from(order));
61	    }
62	}
