1	package com.example.order.order;
2	
3	import com.example.order.coupon.Coupon;
4	import com.example.order.coupon.CouponRepository;
5	import com.example.order.product.Product;
6	import com.example.order.product.ProductRepository;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.function.Function;
10	import java.util.stream.Collectors;
11	import org.springframework.stereotype.Component;
12	import org.springframework.transaction.annotation.Propagation;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	/** 재고 예약/쿠폰 사용 복원 공통 루틴 (설계 3.3). 반드시 호출자의 트랜잭션 안에서 실행된다. */
16	@Component
17	public class OrderInventory {
18	    private final ProductRepository productRepository;
19	    private final CouponRepository couponRepository;
20	
21	    public OrderInventory(ProductRepository productRepository, CouponRepository couponRepository) {
22	        this.productRepository = productRepository;
23	        this.couponRepository = couponRepository;
24	    }
25	
26	    /** 상품 행을 id 오름차순으로 락 걸고 id -> Product 맵으로 돌려준다. */
27	    @Transactional(propagation = Propagation.MANDATORY)
28	    public Map<Long, Product> lockProducts(List<Long> ids) {
29	        return productRepository.lockAllByIdIn(ids).stream()
30	                .collect(Collectors.toMap(Product::getId, Function.identity()));
31	    }
32	
33	    private Map<Long, Product> lockFor(OrderEntity order) {
34	        return lockProducts(order.getItems().stream().map(OrderItem::getProductId).toList());
35	    }
36	
37	    /** PENDING 에서 벗어날 때 (CANCELLED, EXPIRED, PAYMENT_FAILED): reserved 감소. */
38	    @Transactional(propagation = Propagation.MANDATORY)
39	    public void releaseReservation(OrderEntity order) {
40	        Map<Long, Product> products = lockFor(order);
41	        order.getItems().forEach(i -> products.get(i.getProductId()).release(i.getQuantity()));
42	    }
43	
44	    /** 결제 승인: stock, reserved 감소. */
45	    @Transactional(propagation = Propagation.MANDATORY)
46	    public void sell(OrderEntity order) {
47	        Map<Long, Product> products = lockFor(order);
48	        order.getItems().forEach(i -> products.get(i.getProductId()).sell(i.getQuantity()));
49	    }
50	
51	    /** 환불: stock 증가. */
52	    @Transactional(propagation = Propagation.MANDATORY)
53	    public void restoreStock(OrderEntity order) {
54	        Map<Long, Product> products = lockFor(order);
55	        order.getItems().forEach(i -> products.get(i.getProductId()).restock(i.getQuantity()));
56	    }
57	
58	    @Transactional(propagation = Propagation.MANDATORY)
59	    public void restoreCoupon(OrderEntity order) {
60	        if (order.getCouponCode() == null) {
61	            return;
62	        }
63	        Coupon c = couponRepository.lockByCode(order.getCouponCode()).orElseThrow();
64	        c.restore();
65	    }
66	}
