11	
12	/** 결제 대기 만료 스윕 (R6). 후보 조회는 락 없이, 처리는 주문당 트랜잭션 1개. */
13	@Component
14	public class OrderExpirySweeper {
15	    private static final Logger log = LoggerFactory.getLogger(OrderExpirySweeper.class);
16	
17	    private final OrderRepository orderRepository;
18	    private final OrderService orderService;
19	    private final Clock clock;
20	
21	    public OrderExpirySweeper(OrderRepository orderRepository, OrderService orderService, Clock clock) {
22	        this.orderRepository = orderRepository;
23	        this.orderService = orderService;
24	        this.clock = clock;
25	    }
26	
27	    @Scheduled(fixedDelayString = "${order.expiry-sweep-delay-ms:200}")
28	    public void sweep() {
29	        List<Long> ids;
30	        try {
31	            ids = orderRepository.findDueIds(OrderStatus.PENDING_PAYMENT, Times.now(clock), PageRequest.of(0, 100));
32	        } catch (RuntimeException e) {
33	            log.warn("expiry sweep: candidate query failed", e);
34	            return;
35	        }
36	        for (Long id : ids) {
37	            try {
38	                orderService.expireIfDue(id);
