1	package com.example.order.order;
2	
3	import com.example.order.common.ApiException;
4	import com.example.order.common.ErrorCode;
5	import jakarta.persistence.EntityManager;
6	import jakarta.persistence.TypedQuery;
7	import java.util.List;
8	import org.springframework.stereotype.Service;
9	import org.springframework.transaction.annotation.Transactional;
10	
11	@Service
12	public class OrderQueryService {
13	    private final OrderRepository orderRepository;
14	    private final EntityManager em;
15	
16	    public OrderQueryService(OrderRepository orderRepository, EntityManager em) {
17	        this.orderRepository = orderRepository;
18	        this.em = em;
19	    }
20	
21	    @Transactional(readOnly = true)
22	    public OrderResponse get(long id) {
23	        return orderRepository.findById(id).map(OrderResponse::from)
24	                .orElseThrow(() -> new ApiException(ErrorCode.ORDER_NOT_FOUND, "order " + id + " not found"));
25	    }
26	
27	    @Transactional(readOnly = true)
28	    public OrderPageResponse list(String userId, OrderStatus status, int size, OrderCursor cursor) {
29	        StringBuilder jpql = new StringBuilder("select o from OrderEntity o where 1 = 1");
30	        if (userId != null) jpql.append(" and o.userId = :userId");
31	        if (status != null) jpql.append(" and o.status = :status");
32	        if (cursor != null) {
33	            jpql.append(" and (o.createdAt < :cAt or (o.createdAt = :cAt and o.id < :cId))");
34	        }
35	        jpql.append(" order by o.createdAt desc, o.id desc");
36	        TypedQuery<OrderEntity> q = em.createQuery(jpql.toString(), OrderEntity.class);
37	        if (userId != null) q.setParameter("userId", userId);
38	        if (status != null) q.setParameter("status", status);
39	        if (cursor != null) {
40	            q.setParameter("cAt", cursor.createdAt());
41	            q.setParameter("cId", cursor.id());
42	        }
43	        q.setMaxResults(size + 1);
44	        List<OrderEntity> rows = q.getResultList();
45	        boolean hasNext = rows.size() > size;
46	        List<OrderEntity> page = hasNext ? rows.subList(0, size) : rows;
47	        String next = hasNext ? OrderCursor.of(page.get(page.size() - 1)).encode() : null;
48	        return new OrderPageResponse(page.stream().map(OrderResponse::from).toList(), next);
49	    }
50	}
