2	
3	import java.net.http.HttpClient;
4	import org.springframework.http.MediaType;
5	import org.springframework.http.client.JdkClientHttpRequestFactory;
6	import org.springframework.stereotype.Component;
7	import org.springframework.web.client.RestClient;
8	
9	@Component
10	public class RestPaymentGatewayClient implements PaymentGatewayClient {
11	
12	    record PayRequest(long orderId, long amount, String cardToken) {
13	    }
14	
15	    record PayResponse(String paymentId, String status) {
16	    }
17	
18	    record RefundResponse(String paymentId, String status) {
19	    }
20	
21	    private final RestClient restClient;
22	
23	    public RestPaymentGatewayClient(PaymentGatewayProperties props) {
24	        HttpClient httpClient = HttpClient.newBuilder()
25	                .version(HttpClient.Version.HTTP_1_1)
26	                .connectTimeout(props.connectTimeout())
27	                .build();
28	        JdkClientHttpRequestFactory factory = new JdkClientHttpRequestFactory(httpClient);
29	        factory.setReadTimeout(props.readTimeout());
30	        this.restClient = RestClient.builder()
31	                .baseUrl(props.url().toString())
32	                .requestFactory(factory)
33	                .build();
34	    }
35	
36	    @Override
37	    public PgPaymentResult pay(String idempotencyKey, long orderId, long amount, String cardToken) {
38	        PayResponse res;
39	        try {
40	            res = restClient.post()
41	                    .uri("/v1/payments")
42	                    .header("Idempotency-Key", idempotencyKey)
43	                    .contentType(MediaType.APPLICATION_JSON)
44	                    .body(new PayRequest(orderId, amount, cardToken))
45	                    .retrieve()
46	                    .body(PayResponse.class);
47	        } catch (RuntimeException e) {
48	            throw new PaymentGatewayUnavailableException("payment request failed", e);
49	        }
50	        if (res == null || res.paymentId() == null || res.status() == null) {
51	            throw new PaymentGatewayUnavailableException("invalid payment response", null);
52	        }
53	        return switch (res.status()) {
54	            case "APPROVED" -> new PgPaymentResult(res.paymentId(), true);
55	            case "DECLINED" -> new PgPaymentResult(res.paymentId(), false);
56	            default -> throw new PaymentGatewayUnavailableException("unknown payment status " + res.status(), null);
57	        };
58	    }
59	
60	    @Override
61	    public void refund(String paymentId) {
62	        RefundResponse res;
63	        try {
64	            res = restClient.post()
65	                    .uri(b -> b.path("/v1/payments/{paymentId}/refund").build(paymentId))
66	                    .retrieve()
67	                    .body(RefundResponse.class);
68	        } catch (RuntimeException e) {
69	            throw new PaymentGatewayUnavailableException("refund request failed", e);
70	        }
71	        if (res == null || !"REFUNDED".equals(res.status())) {
72	            throw new PaymentGatewayUnavailableException("invalid refund response", null);
73	        }
74	    }
75	}
