        ApiResponse replay = createOrder(user, key, null, p, 1);

        assertThat(replay.status()).isEqualTo(201);
        assertThat(replay.body()).isEqualTo(first.body());
    }

    @Test
    @DisplayName("R4.2 본문의 필드 순서/공백만 다른 같은 요청은 재생")
