        ApiResponse r2 = pay(order.id(), key, "tok");

        assertThat(r1.status()).isEqualTo(409);
        assertThat(r1.code()).isEqualTo("INVALID_STATE");
        assertThat(r2.status()).isEqualTo(409);
        assertThat(r2.code()).isEqualTo("INVALID_STATE");
