        String cursor = null;
        for (int guard = 0; guard < 100; guard++) {
            ApiResponse r = listOrders(query + "&size=" + size + (cursor == null ? "" : "&cursor=" + cursor));
            assertThat(r.status()).isEqualTo(200);
            all.addAll(ids(r.json("content")));
