                headers("X-User-Id", h, "Idempotency-Key", uniqueKey())).status()).isEqualTo(400);
        assertThat(post("/api/orders", "{\"items\":[{\"productId\":" + p + ",\"quantity\":1}],\"couponCode\":123}",
