package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.order.support.AbstractIntegrationTest;
import org.junit.jupiter.api.Test;

class TmpCoercionTest extends AbstractIntegrationTest {
    @Test void t() {
        long p = newProduct(100, 5);
        var h = headers("X-User-Id", "u", "Idempotency-Key", uniqueKey());
        for (String b : new String[]{"{\"items\":[{\"productId\":" + p + ",\"quantity\":1}],\"couponCode\":123}",
                "{\"items\":[{\"productId\":" + p + ",\"quantity\":1}],\"couponCode\":true}"}) {
            var r = post("/api/orders", b, h);
            assertThat(r.status()).as(r.rawBody()).isEqualTo(400);
            assertThat(r.code()).isEqualTo("VALIDATION_ERROR");
        }
        assertThat(post("/api/products", "{\"name\":123,\"price\":1,\"stock\":1}", null).status()).isEqualTo(400);
        assertThat(post("/api/products", "{\"name\":true,\"price\":1,\"stock\":1}", null).status()).isEqualTo(400);
        assertThat(post("/api/products", "{\"name\":1.5,\"price\":1,\"stock\":1}", null).status()).isEqualTo(400);
        assertThat(post("/api/orders/" + p + "/pay", "{\"cardToken\":123}", headers("Idempotency-Key", "k")).status()).isEqualTo(400);
        assertThat(post("/api/coupons", "{\"code\":1234,\"type\":\"FIXED\",\"value\":1,\"totalQuantity\":1,\"validFrom\":\"2026-01-01T00:00:00Z\",\"validUntil\":\"2027-01-01T00:00:00Z\"}", null).status()).isEqualTo(400);
        assertThat(post("/api/products", "{\"name\":\"ok\",\"price\":1,\"stock\":1}", null).status()).isEqualTo(201);
    }
}
EOF
