1	package com.example.order.common;
2	
3	import com.fasterxml.jackson.core.JsonParser;
4	import com.fasterxml.jackson.core.JsonToken;
5	import com.fasterxml.jackson.databind.DeserializationContext;
6	import com.fasterxml.jackson.databind.cfg.CoercionAction;
7	import com.fasterxml.jackson.databind.cfg.CoercionInputShape;
8	import com.fasterxml.jackson.databind.type.LogicalType;
9	import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
10	import com.fasterxml.jackson.datatype.jsr310.deser.InstantDeserializer;
11	import java.io.IOException;
12	import java.time.OffsetDateTime;
13	import org.springframework.boot.autoconfigure.jackson.Jackson2ObjectMapperBuilderCustomizer;
14	import org.springframework.context.annotation.Bean;
15	import org.springframework.context.annotation.Configuration;
16	
17	/**
18	 * Boot 자동 구성 ObjectMapper 를 대체하지 않고 customize 한다 (C2, 설계 01 6.3 "타입 불일치" -> 400).
19	 * - 시각 필드에 JSON 숫자 -> 실패 (epoch 로 받아들이지 않음)
20	 * - 문자열 필드에 JSON 숫자/불리언 -> 실패 (문자열로 강제 변환하지 않음)
21	 */
22	@Configuration
23	public class JacksonConfig {
24	
25	    @Bean
26	    public Jackson2ObjectMapperBuilderCustomizer strictScalarCoercionCustomizer() {
27	        return builder -> builder.deserializerByType(OffsetDateTime.class, new StrictOffsetDateTimeDeserializer())
28	                .postConfigurer(mapper -> {
29	            mapper.coercionConfigFor(LogicalType.DateTime)
30	                    .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail)
31	                    .setCoercion(CoercionInputShape.Float, CoercionAction.Fail);
32	            mapper.coercionConfigFor(LogicalType.Textual)
33	                    .setCoercion(CoercionInputShape.Integer, CoercionAction.Fail)
34	                    .setCoercion(CoercionInputShape.Float, CoercionAction.Fail)
35	                    .setCoercion(CoercionInputShape.Boolean, CoercionAction.Fail);
36	        });
37	    }
38	
39	    /**
40	     * jsr310 의 OffsetDateTime 역직렬화는 숫자 토큰을 epoch 로 받아들이고 CoercionConfig(DateTime)를 보지 않는다.
41	     * 문자열 토큰만 허용하고 실제 파싱은 기존 jsr310 역직렬화기에 위임한다 (오프셋 없는 문자열은 기존대로 실패).
42	     */
43	    static class StrictOffsetDateTimeDeserializer extends StdDeserializer<OffsetDateTime> {
44	        StrictOffsetDateTimeDeserializer() {
45	            super(OffsetDateTime.class);
46	        }
47	
48	        @Override
49	        public OffsetDateTime deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
50	            if (p.currentToken() != JsonToken.VALUE_STRING) {
51	                return (OffsetDateTime) ctxt.handleUnexpectedToken(OffsetDateTime.class, p);
52	            }
53	            return InstantDeserializer.OFFSET_DATE_TIME.deserialize(p, ctxt);
54	        }
55	    }
56	}
